starter_code:
def total(numbers):
    result = 0
    for number in numbers:
        result = number
    return result

solution:
def total(numbers):
    result = 0
    for number in numbers:
        result += number
    return result

starter_code:
def collect(value, items=[]):
    items.append(value)
    return items

solution:
def collect(value, items=None):
    if items is None:
        items = []
    items.append(value)
    return items
